import json
from pathlib import Path
x=json.loads(Path('router/references/tools.json').read_text())
print(type(x).__name__)
if isinstance(x,dict):
 print('keys:',list(x))
 for k,v in x.items():
  if isinstance(v,list):
   for p in v:
    if isinstance(p,dict) and any(s in str(p.get('id','')).lower() for s in ['remotion','ffmpeg']): print(json.dumps(p,indent=2))
p=Path('router/references/recipes.md').read_text()
start=p.find('## Authored')
if start<0:
 for line in p.splitlines():
  if line.startswith('#'): print(line)
else:
 end=p.find('\\n## ',start+1)
 print(p[start:end if end>=0 else None])
print(Path('router/references/handoff.md').read_text())
